command_argv:
import json,pathlib,sys
record=json.loads(pathlib.Path('.ufo/waves/fleet-round-1-interactive/wave-plan-run.json').read_text())
plan=json.loads(record['stdout'])
required={'reviewer':'@m_grok','critic':'@m_grok','sentinel':'@m_grok','scribe':'@m_composer','connector':'@m_antigravity'}
actual={role:'@'+family['alias'] for family in plan['routePreflight']['families'] for role in family['roles']}
missing=[(role,want,actual.get(role)) for role,want in required.items() if actual.get(role)!=want]
for role,want,got in missing: print(f'MISSING_BINDING role={role} required={want} observed={got}')
code=2 if missing else 0
print(f'ROUTING_CONTRACT {"BLOCKED" if missing else "BOUND"} finding={"required_role_alias_binding_missing" if missing else "none"} planned={plan["counts"]["total"]} dispatched=0 exit={code}')
sys.exit(code)
